#     Result: protocol.SubChunkResultSuccess, RawPayload: []byte{0xaa},
#     HeightMapType: protocol.HeightMapDataNone,
#     RenderHeightMapType: protocol.HeightMapDataNone}}}
V1001_UNCACHED = bytes.fromhex("000202040601000000ff00010101aa0000")

