#     Result: protocol.SubChunkResultSuccess, RawPayload: protocol.Option([]byte{0xaa}),
#     HeightMapType: protocol.HeightMapDataNone,
#     RenderHeightMapType: protocol.HeightMapDataNone}}}
V2168_UNCACHED = bytes.fromhex("000201000000020000000300000001ff0001010101aa0000000000")

# generated by gophertunnel b8bd735:
# &packet.SubChunk{CacheEnabled: true, Dimension: 1,
#   Position: protocol.SubChunkPos{1, 2, 3},
