GOLDENS = [
    pytest.param(
        v1001.SubChunkPacket(
            cache_enabled=False,
            dimension_type=1,
            center_pos=v1001.legacy.SubChunkPos(x=1, y=2, z=3),
            uncached_sub_chunk_data=[
                v1001.SubChunkPacket.UncachedSubChunkPacketData(
                    sub_chunk_pos_offset=v1001.SubChunkPacket.SubChunkPosOffset(x=-1, y=0, z=1),
                    result=v1001.SubChunkPacket.SubChunkRequestResult.SUCCESS,
                    serialized_sub_chunk=PAYLOAD_A,
                    height_map_data=v1001.SubChunkPacket.HeightmapData(
                        height_map_type=v1001.SubChunkPacket.HeightMapDataType.NO_DATA,
                        render_height_map_type=v1001.SubChunkPacket.HeightMapDataType.NO_DATA,
                    ),
                )
            ],
        ),
        V1001_UNCACHED,
        id="v1001-cache-off",
    ),
    pytest.param(
        v1001.SubChunkPacket(
            cache_enabled=True,
            dimension_type=1,
            center_pos=v1001.legacy.SubChunkPos(x=1, y=2, z=3),
            sub_chunk_data=[
                v1001.SubChunkPacket.SubChunkPacketData(
                    sub_chunk_pos_offset=v1001.SubChunkPacket.SubChunkPosOffset(x=-1, y=0, z=1),
                    result=v1001.SubChunkPacket.SubChunkRequestResult.SUCCESS_ALL_AIR,
                    height_map_data=v1001.SubChunkPacket.HeightmapData(
                        height_map_type=v1001.SubChunkPacket.HeightMapDataType.HAS_DATA,
                        subchunk_height_map=FULL_HEIGHT_MAP,
                        render_height_map_type=v1001.SubChunkPacket.HeightMapDataType.NO_DATA,
                    ),
                    blob_id=9,
                )
            ],
        ),
        V1001_CACHED,
        id="v1001-cache-on",
    ),
    pytest.param(
        v2168.SubChunkPacket(
            cache_enabled=False,
            dimension_type=1,
            center_pos=v2168.SubChunkPos(x=1, y=2, z=3),
            sub_chunk_data=[
                v2168.SubChunkPacket.SubChunkPacketData(
                    sub_chunk_pos_offset=v2168.SubChunkPacket.SubChunkPosOffset(x=-1, y=0, z=1),
                    result=v2168.SubChunkPacket.SubChunkRequestResult.SUCCESS,
                    serialized_sub_chunk=PAYLOAD_A,
                    height_map_data=v2168.SubChunkPacket.HeightmapData(
                        height_map_type=v2168.SubChunkPacket.HeightMapDataType.NO_DATA,
                        render_height_map_type=v2168.SubChunkPacket.HeightMapDataType.NO_DATA,
                    ),
                )
            ],
        ),
        V2168_UNCACHED,
        id="v2168-cache-off",
    ),
    pytest.param(
        v2168.SubChunkPacket(
            cache_enabled=True,
            dimension_type=1,
            center_pos=v2168.SubChunkPos(x=1, y=2, z=3),
            sub_chunk_data=[
                v2168.SubChunkPacket.SubChunkPacketData(
                    sub_chunk_pos_offset=v2168.SubChunkPacket.SubChunkPosOffset(x=-1, y=0, z=1),
                    result=v2168.SubChunkPacket.SubChunkRequestResult.SUCCESS_ALL_AIR,
                    height_map_data=v2168.SubChunkPacket.HeightmapData(
                        height_map_type=v2168.SubChunkPacket.HeightMapDataType.HAS_DATA,
                        subchunk_height_map=FULL_HEIGHT_MAP,
                        render_height_map_type=v2168.SubChunkPacket.HeightMapDataType.NO_DATA,
                    ),
                    blob_id=9,
                )
            ],
        ),
        V2168_CACHED,
        id="v2168-cache-on",
    ),
]


@pytest.mark.parametrize("version", [v975, v1001, v2168])
def test_sub_chunk_is_packet_174(version):
    assert version.PACKETS[174] is version.SubChunkPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_sub_chunk_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_sub_chunk_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_sub_chunk_is_unchanged_between_v975_and_v1001():
    packet = v975.SubChunkPacket(
        cache_enabled=False,
        dimension_type=1,
        center_pos=v975.legacy.SubChunkPos(x=1, y=2, z=3),
        uncached_sub_chunk_data=[
            v975.SubChunkPacket.UncachedSubChunkPacketData(
                sub_chunk_pos_offset=v975.SubChunkPacket.SubChunkPosOffset(x=-1, y=0, z=1),
                result=v975.SubChunkPacket.SubChunkRequestResult.SUCCESS,
                serialized_sub_chunk=PAYLOAD_A,
                height_map_data=v975.SubChunkPacket.HeightmapData(
                    height_map_type=v975.SubChunkPacket.HeightMapDataType.NO_DATA,
                    render_height_map_type=v975.SubChunkPacket.HeightMapDataType.NO_DATA,
                ),
            )
        ],
    )
    assert bytes(packet) == V1001_UNCACHED


def test_a_v1001_sub_chunk_body_does_not_decode_as_a_v2168_one():
    with pytest.raises(ValueError, match="at byte"):
        v2168.SubChunkPacket.from_bytes(V1001_UNCACHED)


def test_a_v2168_sub_chunk_body_does_not_decode_as_a_v1001_one():
    with pytest.raises(ValueError, match="at byte"):
        v1001.SubChunkPacket.from_bytes(V2168_UNCACHED)
